styles:
.reader-quote {
  font-style: italic;
  color: #ffff00;
  background: rgba(255, 255, 0, 0.08);
  padding: 0 3px;
  font-weight: 600;
}
.reader-ellipsis {
  letter-spacing: 10px;
  color: #ff6600;
}
.reader-dash {
  letter-spacing: 4px;
  color: #ff3333;
  font-weight: 700;
}
.reader-speak {
  color: #39ff14;
  font-weight: 900;
  font-size: 1.1em;
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 4em;
  line-height: 0.65;
  padding-right: 10px;
  padding-top: 4px;
  color: #ff3333;
  font-weight: 900;
  text-shadow: 2px 2px 0 #000;
}
